import { sql } from "drizzle-orm";
import { check, index, integer, jsonb, pgTable, text, uuid } from "drizzle-orm/pg-core";

import { createdAt, id, instant, timestamps, version } from "../columns";

/**
 * Platform-wide tables (04-veri §10, adapted by plan K-07 and K-15). Auth tables are generated by
 * the Better Auth CLI into ./auth.ts. Venue tables (venues, venue_domains, venue_settings,
 * menus …) arrive with D-02 / D-03 and carry row level security (ADR-0004).
 *
 * Not used in this project: site_settings (→ platform_settings + venue_settings), leads and
 * consent_records (no visitor form, no visitor personal data — K-15).
 */

/** Single-row, versioned platform configuration (name, introduction texts, SEO). */
export const platformSettings = pgTable(
  "platform_settings",
  {
    id: text().primaryKey().default("singleton"),
    name: text().notNull(),
    tagline: text().notNull(),
    description: text().notNull(),
    contact: jsonb().$type<{ phone: string; email: string }>().notNull(),
    legalName: text().notNull(),
    seo: jsonb().$type<{ titleTemplate: string; defaultDescription: string }>().notNull(),
    ...version,
    ...timestamps,
  },
  (table) => [check("ck_platform_settings_singleton", sql`${table.id} = 'singleton'`)],
);

/**
 * Messages that would have been sent in demo (02-mimari §5): panel invitations and password
 * resets while PLATFORM_DEMO=true, and — later — a demo venue's own messages (waiter call, P2).
 * venue_id gets its foreign key to venues in D-02.
 */
export const demoOutbox = pgTable(
  "demo_outbox",
  {
    id: id(),
    venueId: uuid(),
    channel: text().notNull(),
    to: text().notNull(),
    template: text().notNull(),
    data: jsonb().$type<Record<string, unknown>>().notNull(),
    relatedId: text(),
    ...createdAt,
  },
  (table) => [index("ix_demo_outbox_venue_created_at").on(table.venueId, table.createdAt)],
);

/** Fixed-window counters for action rate limits (11-guvenlik §9). Auth has its own limiter. */
export const actionRateLimits = pgTable("action_rate_limits", {
  key: text().primaryKey(),
  count: integer().notNull().default(0),
  expiresAt: instant().notNull(),
});

/**
 * Who changed what (A-02). venue_id is null for platform-level actions (venue created, domain
 * bound); it gets its foreign key to venues in D-02.
 */
export const auditLogs = pgTable(
  "audit_logs",
  {
    id: id(),
    venueId: uuid(),
    actorId: text(),
    action: text().notNull(), // availability.sold_out, prices.bulk_apply, platform.domain_bind…
    entity: text(),
    entityId: text(),
    changes: jsonb().$type<Record<string, { from: unknown; to: unknown }>>(),
    ipHash: text(),
    ...createdAt,
  },
  (table) => [
    index("ix_audit_logs_entity").on(table.entity, table.entityId, table.createdAt),
    index("ix_audit_logs_venue_created_at").on(table.venueId, table.createdAt),
  ],
);
